import{flushEveCliTelemetry}from"#cli/telemetry/flush.js";import{readEveTelemetryPreference,setEveTelemetryEnabled}from"#cli/telemetry/preference.js";function registerEveTelemetryCommands(e,t){let n=e.command(`telemetry`).description(`Enable or disable CLI telemetry collection.`);n.command(`status`).description(`Show whether telemetry collection is enabled.`).action(async()=>{await showEveTelemetryStatus(t)}),n.command(`enable`).description(`Enable telemetry collection.`).action(async()=>{await enableEveTelemetry(t)}),n.command(`disable`).description(`Disable telemetry collection.`).action(async()=>{await disableEveTelemetry(t)}),n.command(`flush <payload>`,{hidden:!0}).action(async e=>{await flushEveCliTelemetry(e)})}async function showEveTelemetryStatus(e){let{enabled:t}=await readEveTelemetryPreference();e.log(`Telemetry status: ${t?`Enabled`:`Disabled`}`)}async function enableEveTelemetry(e){await setEveTelemetryEnabled(!0),e.log(`Telemetry collection enabled.`)}async function disableEveTelemetry(e){await setEveTelemetryEnabled(!1),e.log(`Telemetry collection disabled. No data will be collected from this machine.`)}export{disableEveTelemetry,enableEveTelemetry,registerEveTelemetryCommands,showEveTelemetryStatus};